const { app, BrowserWindow, ipcMain, dialog, safeStorage, Menu, MenuItem, session, shell } = require('electron');
const path = require('node:path');
const fs = require('node:fs/promises');
const { createReadStream } = require('node:fs');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const { execFile } = require('node:child_process');
const { promisify } = require('node:util');
const { pathToFileURL, fileURLToPath } = require('node:url');
const execFileAsync = promisify(execFile);

function secureStorageAvailable(){return !!safeStorage.isEncryptionAvailable?.()&&(process.platform!=='linux'||!['basic_text','unknown'].includes(safeStorage.getSelectedStorageBackend()));}
let interfaceLanguage='nl';
let configuredRoot='';
const defaultRoot = () => path.join(app.getPath('documents'), 'Takevera');
const legacyDefaultRoot = () => path.join(app.getPath('documents'), 'ScriptStudio');
const root = () => configuredRoot || defaultRoot();
async function ensure() {
  await fs.mkdir(root(), {recursive:true, mode:0o700});
  // Restrict the app-managed default folder, but leave user-selected shared folders alone.
  if ([defaultRoot(),legacyDefaultRoot()].some(directory=>path.resolve(root())===path.resolve(directory))) {
    await fs.chmod(root(), 0o700).catch(error => { if (error.code !== 'EPERM' && error.code !== 'EACCES') throw error; });
    for (const name of await fs.readdir(root())) if (/^[a-zA-Z0-9_-]{1,80}\.(?:json(?:\.bak)?|backup-\d+\.bak|recovery-\d+(?:-[a-f0-9]+)?\.bak|corrupt-\d+\.bak)$/.test(name)) await fs.chmod(path.join(root(),name),0o600).catch(()=>{});
  }
}
async function ensurePrivateDirectory(directory) { await fs.mkdir(directory,{recursive:true,mode:0o700}); await fs.chmod(directory,0o700); }
async function ensureProjectAssetDirectory(id) { const assetsRoot=path.join(root(),'assets'); await ensurePrivateDirectory(assetsRoot); const projectDirectory=path.join(assetsRoot,safeProjectId(id)); await ensurePrivateDirectory(projectDirectory); return projectDirectory; }
async function writePrivateFile(file, data, options={}) { const normalized=typeof options==='string'?{encoding:options}:options; await fs.writeFile(file, data, {...normalized, mode:0o600}); await fs.chmod(file,0o600); }
async function verifyExportFile(file,expected){const actual=await fs.readFile(file),bytes=Buffer.isBuffer(expected)?expected:Buffer.from(expected,'utf8');if(!actual.equals(bytes))throw new Error(interfaceLanguage==='nl'?'Exportcontrole mislukt: het opgeslagen bestand komt niet overeen. Het bestand kan wel bestaan.':'Export verification failed: the saved file differs. The file may still exist.');return actual}
async function copyPrivateFile(source, destination) { await fs.copyFile(source,destination); await fs.chmod(destination,0o600); }
const projectArrayFields=['scenes','characters','people','locations','shootDays','shots','shortlists','tasks','equipment','moodboard','storyboard','timelineEvents','productionTemplates','productionPresets','customBookSections'];
const sceneArrayFields=['elements','comments','inventory','images'];
function isRecord(value){return !!value&&typeof value==='object'&&!Array.isArray(value)}
function isObjectArray(value){return Array.isArray(value)&&value.every(isRecord)}
function isProjectData(value,id){return isRecord(value)&&typeof value.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(value.id)&&(!id||value.id===id)&&typeof value.title==='string'&&isObjectArray(value.scenes)&&projectArrayFields.every(key=>value[key]===undefined||isObjectArray(value[key]))&&value.scenes.every(scene=>sceneArrayFields.every(key=>scene[key]===undefined||isObjectArray(scene[key])))}
const ipcErrorTranslations={};
async function localizedIpcError(error){const message=String(error?.message||error||'Unexpected error');let translations=ipcErrorTranslations[interfaceLanguage];if(!translations){try{const locale=JSON.parse(await fs.readFile(path.join(__dirname,'..','locales',`${interfaceLanguage}.json`),'utf8'));translations={messages:locale.errorMessages||{},codes:locale.errorCodes||{}}}catch{translations={messages:{},codes:{}}}ipcErrorTranslations[interfaceLanguage]=translations}return translations.messages[message]||translations.codes[String(error?.code||'')]||message}
const trustedAppContents=new WeakSet();
function isTrustedAppSender(event){
  if(!event.sender||!trustedAppContents.has(event.sender)||!event.senderFrame||event.senderFrame!==event.sender.mainFrame)return false;
  try{const url=new URL(event.senderFrame.url);url.search='';url.hash='';return url.href===pathToFileURL(path.join(__dirname,'index.html')).href}catch{return false}
}
const registerIpcHandler=ipcMain.handle.bind(ipcMain);
ipcMain.handle=(channel,handler)=>registerIpcHandler(channel,async(event,...args)=>{try{if(!isTrustedAppSender(event))throw new Error('Untrusted application sender');return await handler(event,...args)}catch(error){throw new Error(await localizedIpcError(error))}});
async function list() { await ensure(); const names=await fs.readdir(root()); const out=[]; for(const name of names){ if(!name.endsWith('.json'))continue; try{const value=JSON.parse(await fs.readFile(path.join(root(),name),'utf8'));if(isProjectData(value,name.slice(0,-5)))out.push(value)}catch{} } return out.sort((a,b)=>b.updatedAt-a.updatedAt); }
function window(){ const w=new BrowserWindow({width:1440,height:960,minWidth:680,minHeight:600,backgroundColor:'#f5f4f0',title:'Takevera',icon:path.join(__dirname,'assets','takevera-logo.png'),webPreferences:{preload:path.join(__dirname,'preload.cjs'),contextIsolation:true,nodeIntegration:false,sandbox:true,spellcheck:true}});trustedAppContents.add(w.webContents);w.webContents.setWindowOpenHandler(()=>({action:'deny'}));w.webContents.on('will-frame-navigate',event=>event.preventDefault());w.webContents.on('context-menu',(_,params)=>{const menu=new Menu(),nl=interfaceLanguage==='nl',append=(label,role,enabled=true)=>menu.append(new MenuItem({label,role,enabled}));if(params.misspelledWord){const suggestions=params.dictionarySuggestions||[];for(const suggestion of suggestions.slice(0,8))menu.append(new MenuItem({label:suggestion,click:()=>w.webContents.replaceMisspelling(suggestion)}));if(suggestions.length)menu.append(new MenuItem({type:'separator'}));menu.append(new MenuItem({label:nl?'Toevoegen aan woordenboek':'Add to dictionary',click:()=>w.webContents.session.addWordToSpellCheckerDictionary(params.misspelledWord)}))}if(params.isEditable){if(menu.items.length)menu.append(new MenuItem({type:'separator'}));append(nl?'Ongedaan maken':'Undo','undo');append(nl?'Opnieuw':'Redo','redo');menu.append(new MenuItem({type:'separator'}));append(nl?'Knippen':'Cut','cut',!!params.editFlags?.canCut);append(nl?'Kopiëren':'Copy','copy',!!params.editFlags?.canCopy);append(nl?'Plakken':'Paste','paste',!!params.editFlags?.canPaste);menu.append(new MenuItem({type:'separator'}));append(nl?'Alles selecteren':'Select all','selectAll')}else if(params.selectionText){append(nl?'Kopiëren':'Copy','copy',!!params.editFlags?.canCopy)}if(menu.items.length)menu.popup({window:w})});w.loadFile(path.join(__dirname,'index.html')); }
async function loadConfiguredRoot(){try{const data=JSON.parse(await fs.readFile(path.join(app.getPath('userData'),'project-storage.json'),'utf8'));if(typeof data.path==='string'&&path.isAbsolute(data.path))return path.resolve(data.path)}catch(error){if(error.code!=='ENOENT')console.error(`Could not read project storage setting: ${error.message}`)}const hasProjects=async directory=>{try{for(const name of await fs.readdir(directory)){if(!name.endsWith('.json'))continue;try{const data=JSON.parse(await fs.readFile(path.join(directory,name),'utf8'));if(isProjectData(data,name.slice(0,-5)))return true}catch{}}}catch{}return false};if(await hasProjects(defaultRoot()))return defaultRoot();if(await hasProjects(legacyDefaultRoot()))return legacyDefaultRoot();for(const directory of [defaultRoot(),legacyDefaultRoot()])try{if((await fs.stat(directory)).isDirectory())return directory}catch{}return defaultRoot()}
app.whenReady().then(async()=>{configuredRoot=await loadConfiguredRoot();await ensure();window();app.on('activate',()=>{if(!BrowserWindow.getAllWindows().length)window()})}); app.on('window-all-closed',()=>{if(process.platform!=='darwin')app.quit()});
function safeProjectId(id){if(typeof id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(id))throw new Error('Invalid project ID');return id}
ipcMain.handle('projects:recoverable',async()=>{await ensure();const names=await fs.readdir(root()),backupPattern=/^([a-zA-Z0-9_-]{1,80})\.(?:json\.bak|backup-\d+\.bak|recovery-\d+(?:-[a-f0-9]{6})?\.bak)$/,mainPattern=/^([a-zA-Z0-9_-]{1,80})\.json$/,corruptPattern=/^([a-zA-Z0-9_-]{1,80})\.corrupt-\d+\.bak$/,ids=[...new Set([...names.map(name=>backupPattern.exec(name)?.[1]),...names.map(name=>mainPattern.exec(name)?.[1]),...names.map(name=>corruptPattern.exec(name)?.[1])].filter(Boolean))],out=[];for(const id of ids){let currentValid=false,currentTitle='',mainInfo=null;try{const file=path.join(root(),`${id}.json`),raw=await fs.readFile(file,'utf8'),current=JSON.parse(raw);currentValid=isProjectData(current,id);currentTitle=typeof current?.title==='string'?current.title:'';mainInfo=await fs.stat(file)}catch(error){if(error.code!=='ENOENT'){try{mainInfo=await fs.stat(path.join(root(),`${id}.json`));const raw=await fs.readFile(path.join(root(),`${id}.json`),'utf8'),match=raw.match(/\"title\"\s*:\s*(\"(?:\\.|[^\"\\])*\")/);if(match)currentTitle=JSON.parse(match[1])}catch{}}}if(currentValid)continue;const candidates=[];for(const name of names.filter(item=>backupPattern.exec(item)?.[1]===id)){try{const file=path.join(root(),name),data=JSON.parse(await fs.readFile(file,'utf8')),info=await fs.stat(file);if(isProjectData(data,id))candidates.push({name,data,mtime:info.mtimeMs,size:info.size})}catch{}}candidates.sort((a,b)=>b.mtime-a.mtime);if(candidates[0])out.push({id,title:candidates[0].data.title||currentTitle,name:candidates[0].name,updatedAt:candidates[0].data.updatedAt||candidates[0].mtime,size:candidates[0].size,recoverable:true});else if(mainInfo||names.some(name=>backupPattern.exec(name)?.[1]===id))out.push({id,title:currentTitle,name:'',updatedAt:mainInfo?.mtimeMs||0,size:mainInfo?.size||0,recoverable:false})}return out.sort((a,b)=>b.updatedAt-a.updatedAt)});
ipcMain.handle('projects:backups:list',async(_,rawId)=>{const id=safeProjectId(rawId);await ensure();const names=await fs.readdir(root());const files=names.filter(name=>name===`${id}.json.bak`||new RegExp(`^${id}\\.(?:backup-\\d+|recovery-\\d+(?:-[a-f0-9]{6})?)\\.bak$`).test(name)||new RegExp(`^${id}\\.corrupt-\\d+\\.bak$`).test(name));const out=[];for(const name of files){try{const file=path.join(root(),name),info=await fs.stat(file);let json=null;try{if(info.isFile()&&info.size<=50*1024*1024)json=JSON.parse(await fs.readFile(file,'utf8'))}catch{}const corrupt=name.includes('.corrupt-')||!isProjectData(json,id);out.push({name,updatedAt:!corrupt&&Number.isFinite(Number(json.updatedAt))?Number(json.updatedAt)||info.mtimeMs:info.mtimeMs,size:info.size,title:!corrupt&&typeof json.title==='string'?json.title:'',corrupt})}catch{}}return out.sort((a,b)=>b.updatedAt-a.updatedAt)});
ipcMain.handle('projects:backups:read',async(_,rawId,rawName)=>{const id=safeProjectId(rawId);if(typeof rawName!=='string'||!(rawName===`${id}.json.bak`||new RegExp(`^${id}\\.(?:backup-\\d+|recovery-\\d+(?:-[a-f0-9]{6})?)\\.bak$`).test(rawName)))throw new Error('Invalid backup file');await ensure();const file=path.join(root(),rawName),info=await fs.stat(file);if(!info.isFile()||info.size>50*1024*1024)throw new Error('Backup exceeds the 50 MB limit');const data=JSON.parse(await fs.readFile(file,'utf8'));if(!isProjectData(data,id))throw new Error('Backup does not contain a valid project');return data});
ipcMain.handle('projects:backups:delete',async(_,rawId,rawName)=>{const id=safeProjectId(rawId);if(typeof rawName!=='string'||!(rawName===`${id}.json.bak`||new RegExp(`^${id}\\.backup-\\d+\\.bak$`).test(rawName)||new RegExp(`^${id}\\.recovery-\\d+(?:-[a-f0-9]{6})?\\.bak$`).test(rawName)||new RegExp(`^${id}\\.corrupt-\\d+\\.bak$`).test(rawName)))throw new Error('Invalid backup file');await ensure();await fs.rm(path.join(root(),rawName),{force:true});return true});
ipcMain.handle('projects:backups:restore',async(_,rawId,rawName)=>{const id=safeProjectId(rawId);if(typeof rawName!=='string'||!(rawName===`${id}.json.bak`||new RegExp(`^${id}\\.backup-\\d+\\.bak$`).test(rawName)||new RegExp(`^${id}\\.recovery-\\d+(?:-[a-f0-9]{6})?\\.bak$`).test(rawName)))throw new Error('Invalid backup file');await ensure();const file=path.join(root(),`${id}.json`),backup=path.join(root(),rawName);const data=JSON.parse(await fs.readFile(backup,'utf8'));if(!isProjectData(data,id))throw new Error('Backup does not contain a valid project');let current=null;try{current=JSON.parse(await fs.readFile(file,'utf8'));if(isProjectData(current,id)){let recovery=path.join(root(),`${id}.recovery-${Date.now()}.bak`);while(true){try{await fs.access(recovery);recovery=path.join(root(),`${id}.recovery-${Date.now()+1}.bak`)}catch{break}}await copyPrivateFile(file,recovery)}else{const corrupt=path.join(root(),`${id}.corrupt-${Date.now()}.bak`);await fs.rename(file,corrupt);await fs.chmod(corrupt,0o600)}}catch(error){if(error.code!=='ENOENT'&&!(error instanceof SyntaxError))throw error;if(error instanceof SyntaxError){const corrupt=path.join(root(),`${id}.corrupt-${Date.now()}.bak`);await fs.rename(file,corrupt);await fs.chmod(corrupt,0o600)}}data.updatedAt=Date.now();const temporary=`${file}.restore.tmp`;try{await writePrivateFile(temporary,JSON.stringify(data,null,2),'utf8');await fs.rename(temporary,file)}catch(error){await fs.rm(temporary,{force:true});throw error}return data});
ipcMain.handle('projects:list',list);
async function pruneAutomaticBackups(id,keep=10){const names=await fs.readdir(root()),files=names.filter(name=>name===`${id}.json.bak`||new RegExp(`^${id}\\.backup-\\d+\\.bak$`).test(name)),records=await Promise.all(files.map(async name=>({name,mtime:(await fs.stat(path.join(root(),name))).mtimeMs})));records.sort((a,b)=>b.mtime-a.mtime);for(const item of records.slice(keep))await fs.rm(path.join(root(),item.name),{force:true})}
async function saveProjectData(project){if(!project||typeof project!=='object'||Array.isArray(project))throw new Error('Invalid project');const id=safeProjectId(project.id);await ensure();project.updatedAt=Date.now();const file=path.join(root(),`${id}.json`),temporary=`${file}.tmp`;try{const old=JSON.parse(await fs.readFile(file,'utf8'));if(Date.now()-old.updatedAt>30000){let timestamp=Date.now(),backup=path.join(root(),`${id}.backup-${timestamp}.bak`);while(true){try{await fs.access(backup);timestamp++;backup=path.join(root(),`${id}.backup-${timestamp}.bak`)}catch{break}}await copyPrivateFile(file,backup);await pruneAutomaticBackups(id)}}catch(error){if(error.code!=='ENOENT')console.error(`Could not create project backup: ${error.message}`)}try{await writePrivateFile(temporary,JSON.stringify(project,null,2),'utf8');await fs.rename(temporary,file)}catch(error){await fs.rm(temporary,{force:true});throw error}return project.updatedAt}
ipcMain.handle('projects:save',async(_,project)=>saveProjectData(project));
ipcMain.handle('links:open',async(_,value)=>{if(typeof value!=='string'||value.length>2048)throw new Error('Invalid link');let url;try{url=new URL(value)}catch{throw new Error('Invalid link')}if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new Error('Only public HTTP or HTTPS links can be opened');await shell.openExternal(url.href);return true});
ipcMain.handle('projects:delete',async(_,rawId)=>{const id=safeProjectId(rawId);await fs.rm(path.join(root(),`${id}.json`),{force:true});for(const name of await fs.readdir(root()))if(name===`${id}.json.bak`||new RegExp(`^${id}\\.(?:backup-\\d+|recovery-\\d+(?:-[a-f0-9]{6})?)\\.bak$`).test(name)||new RegExp(`^${id}\\.corrupt-\\d+\\.bak$`).test(name))await fs.rm(path.join(root(),name),{force:true}); await fs.rm(path.join(root(),'assets',id),{recursive:true,force:true}); return true});
ipcMain.handle('assets:add',async(_,rawId)=>{const id=safeProjectId(rawId),result=await dialog.showOpenDialog({properties:['openFile'],filters:[{name:'Images',extensions:['png','jpg','jpeg','webp']}]});if(result.canceled||!result.filePaths[0])return null;const choice=await dialog.showMessageBox({type:'question',title:interfaceLanguage==='nl'?'Afbeelding toevoegen':'Add image',message:interfaceLanguage==='nl'?'Hoe wil je deze afbeelding bewaren?':'How would you like to store this image?',detail:interfaceLanguage==='nl'?'Kopiëren maakt het project zelfstandig. Koppelen gebruikt het bestand op de huidige locatie.':'Copying makes the project self-contained. Linking uses the file at its current location.',buttons:interfaceLanguage==='nl'?['Kopiëren naar project','Oorspronkelijke locatie koppelen','Annuleren']:['Copy into project','Link original location','Cancel'],defaultId:0,cancelId:2});if(choice.response===2)return null;const source=result.filePaths[0];if(choice.response===1)return {src:pathToFileURL(source).href,storageMode:'linked'};const dir=await ensureProjectAssetDirectory(id);const dest=path.join(dir,`${Date.now()}-${path.basename(source)}`);await copyPrivateFile(source,dest);return {src:pathToFileURL(dest).href,storageMode:'copied'}});
ipcMain.handle('assets:add-dropped',async(_,rawId,rawPaths)=>{const id=safeProjectId(rawId);if(!Array.isArray(rawPaths)||!rawPaths.length||rawPaths.length>20)throw new Error('Drop between 1 and 20 images at a time');const sources=[];let totalBytes=0;for(const rawPath of rawPaths){if(typeof rawPath!=='string'||rawPath.length>4096||!path.isAbsolute(rawPath))throw new Error('Invalid dropped image path');const source=path.resolve(rawPath),extension=path.extname(source).toLowerCase(),mime=({'.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp'})[extension];if(!mime)throw new Error(`Unsupported image format: ${path.basename(source)}`);const stat=await fs.stat(source);if(!stat.isFile()||stat.size<12||stat.size>15*1024*1024||(totalBytes+=stat.size)>28*1024*1024)throw new Error('Dropped images exceed the 28 MB limit');const handle=await fs.open(source,'r');const header=Buffer.alloc(12);try{await handle.read(header,0,12,0)}finally{await handle.close()}const valid=mime==='image/png'?header.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):mime==='image/jpeg'?header[0]===255&&header[1]===216&&header[2]===255:header.toString('ascii',0,4)==='RIFF'&&header.toString('ascii',8,12)==='WEBP';if(!valid)throw new Error(`File contents do not match the image extension: ${path.basename(source)}`);sources.push(source)}const count=sources.length,nl=interfaceLanguage==='nl',choice=await dialog.showMessageBox({type:'question',title:nl?'Afbeeldingen toevoegen':'Add images',message:nl?`${count} afbeelding${count===1?'':'en'} aan dit project toevoegen?`:`Add ${count} image${count===1?'':'s'} to this project?`,detail:nl?'Kopiëren bewaart de afbeeldingen in het project. Koppelen laat ze op hun huidige locatie staan.':'Copying stores the images in the project. Linking keeps them at their current locations.',buttons:nl?['Kopiëren naar project','Oorspronkelijke locatie koppelen','Annuleren']:['Copy into project','Link original locations','Cancel'],defaultId:0,cancelId:2});if(choice.response===2)return [];if(choice.response===1)return sources.map(source=>({src:pathToFileURL(source).href,storageMode:'linked'}));const dir=await ensureProjectAssetDirectory(id);const created=[];try{for(const source of sources){const dest=path.join(dir,`${Date.now()}-${crypto.randomBytes(4).toString('hex')}-${path.basename(source)}`);await copyPrivateFile(source,dest);created.push(dest)}return created.map(dest=>({src:pathToFileURL(dest).href,storageMode:'copied'}))}catch(error){for(const file of created)await fs.rm(file,{force:true});throw error}});
ipcMain.handle('assets:check-linked',async(_,sources)=>{if(!Array.isArray(sources)||sources.length>500)return [];return Promise.all(sources.filter(src=>typeof src==='string'&&src.length<=4096&&src.startsWith('file:')).map(async src=>{try{await fs.access(fileURLToPath(src));return {src,available:true}}catch{return {src,available:false}}}))});
ipcMain.handle('projects:folder',async()=>{await ensure();return root()});
function pathContains(parent,child){const relative=path.relative(parent,child);return relative===''||(!path.isAbsolute(relative)&&relative!=='..'&&!relative.startsWith(`..${path.sep}`))}
async function hashFile(file){const hash=crypto.createHash('sha256');for await(const chunk of createReadStream(file))hash.update(chunk);return hash.digest('hex')}
async function directoryManifest(directory,base=directory,result=new Map()){for(const entry of await fs.readdir(directory,{withFileTypes:true})){const full=path.join(directory,entry.name),relative=path.relative(base,full);if(entry.isDirectory()){result.set(relative,'directory');await directoryManifest(full,base,result)}else if(entry.isFile()){const info=await fs.stat(full);result.set(relative,`file:${info.size}:${await hashFile(full)}`)}else throw new Error(`Storage move stopped: unsupported file type at ${relative}`)}return result}
async function rewriteProjectAssetUrls(directory,oldRoot,newRoot){let rewritten=0;const names=await fs.readdir(directory);for(const name of names){if(!name.endsWith('.json')&&!name.endsWith('.bak'))continue;const file=path.join(directory,name);let data;try{data=JSON.parse(await fs.readFile(file,'utf8'))}catch{continue}let changed=false;const visit=value=>{if(!value||typeof value!=='object')return;if(!Array.isArray(value)&&value.storageMode==='copied'&&typeof value.src==='string'&&value.src.startsWith('file:')){try{const source=fileURLToPath(value.src),relative=path.relative(oldRoot,source);if(!path.isAbsolute(relative)&&relative!=='..'&&!relative.startsWith(`..${path.sep}`)){value.src=pathToFileURL(path.join(newRoot,relative)).href;changed=true;rewritten++}}catch{}}for(const child of Object.values(value))visit(child)};visit(data);if(changed){const temporary=`${file}.move.tmp`;await fs.writeFile(temporary,JSON.stringify(data,null,2),'utf8');await fs.rename(temporary,file)}}return rewritten}
async function verifyMovedAssetUrls(directory,targetRoot,stagingRoot){for(const name of await fs.readdir(directory)){if(!name.endsWith('.json')&&!name.endsWith('.bak'))continue;let data;try{data=JSON.parse(await fs.readFile(path.join(directory,name),'utf8'))}catch{continue}const checks=[];const visit=value=>{if(!value||typeof value!=='object')return;if(!Array.isArray(value)&&value.storageMode==='copied'&&typeof value.src==='string'&&value.src.startsWith('file:')){try{const source=fileURLToPath(value.src),relative=path.relative(targetRoot,source);if(!path.isAbsolute(relative)&&relative!=='..'&&!relative.startsWith(`..${path.sep}`))checks.push(fs.access(path.join(stagingRoot,relative)))}catch(error){checks.push(Promise.reject(error))}}for(const child of Object.values(value))visit(child)};visit(data);await Promise.all(checks)}}
