ipcMain.handle('script:docx:import',async()=>{const result=await dialog.showOpenDialog({properties:['openFile'],filters:[{name:'Word document',extensions:['docx']}]});if(result.canceled||!result.filePaths[0])return null;const stat=await fs.stat(result.filePaths[0]);if(stat.size>30*1024*1024)throw new Error('DOCX file exceeds 30 MB');const archive=await fs.readFile(result.filePaths[0]),xml=readZipText(archive,'word/document.xml');if(!xml.includes('<w:document')&&!xml.includes(':document'))throw new Error('DOCX document XML is invalid');const custom=readZipText(archive,'customXml/item1.xml'),match=custom?.match(/<scriptstudio:data>([A-Za-z0-9+/=]+)<\/scriptstudio:data>/);let embeddedProject='';if(match){if(match[1].length>16*1024*1024)throw new Error('Embedded Takevera project exceeds supported size');embeddedProject=Buffer.from(match[1],'base64').toString('utf8')}return {xml,embeddedProject,name:path.basename(result.filePaths[0])}});
