function validateCollaborationAdminEndpoint(raw){if(typeof raw!=='string'||raw.length>200)throw new Error('Invalid local admin URL');const url=new URL(raw);if(url.protocol!=='http:'||url.hostname!=='127.0.0.1'||url.username||url.password||url.search||url.hash||!['','/'].includes(url.pathname))throw new Error('The admin service must use http://127.0.0.1 on this device');const port=Number(url.port||1235);if(!Number.isInteger(port)||port<1024||port>65535)throw new Error('Admin port must be from 1024 to 65535');return `http://127.0.0.1:${port}`}
