async function readAISettings(){try{return JSON.parse(await fs.readFile(aiSettingsFile(),'utf8'))}catch{return {endpoint:'',model:'',provider:'compatible',encryptedKey:''}}}
function validateAIEndpoint(raw){if(typeof raw!=='string'||raw.length>2048)throw new Error('Invalid AI endpoint');const url=new URL(raw);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw new Error('Use an HTTPS endpoint or an HTTP endpoint on localhost');const local=['localhost','127.0.0.1','::1','[::1]'].includes(url.hostname);if(url.protocol!=='https:'&&!local)throw new Error('HTTP is allowed only for a local model endpoint');return url}
const aiProviderEndpoints={claude:'https://api.anthropic.com/v1',gemini:'https://generativelanguage.googleapis.com/v1beta/openai',grok:'https://api.x.ai/v1'};
function normalizedAIEndpoint(value){return value?validateAIEndpoint(value).href.replace(/\/$/,''):''}
ipcMain.handle('ai:settings:get',async()=>{const saved=await readAISettings();return {endpoint:saved.endpoint||'',model:saved.model||'',provider:saved.provider||'compatible',workspaceId:saved.workspaceId||'',hasKey:!!saved.encryptedKey,secureStorage:secureStorageAvailable()}});
ipcMain.handle('ai:settings:save',async(_,raw)=>{
  if(!raw||typeof raw!=='object')throw new Error('Invalid AI settings');
  const provider=String(raw.provider||'compatible');if(!['compatible','local','claude','gemini','grok'].includes(provider))throw new Error('Invalid AI provider');
  const endpoint=aiProviderEndpoints[provider]||String(raw.endpoint||'').trim(),model=String(raw.model||'').trim(),workspaceId=provider==='claude'?String(raw.workspaceId||'').trim():'';
  if(endpoint)validateAIEndpoint(endpoint);if(model.length>160)throw new Error('Model name is too long');if(workspaceId&&!/^[A-Za-z0-9_-]{1,128}$/.test(workspaceId))throw new Error('Invalid Claude workspace ID');
  const previous=await readAISettings(),newKey=typeof raw.apiKey==='string'?raw.apiKey.trim():'';let encryptedKey=previous.encryptedKey||'';
  if(encryptedKey&&!raw.clearKey&&!newKey&&((previous.provider||'compatible')!==provider||normalizedAIEndpoint(previous.endpoint||'')!==normalizedAIEndpoint(endpoint)))throw new Error('Provide a new API key or remove the saved key when changing AI provider or endpoint');
  if(newKey){if(!secureStorageAvailable())throw new Error('Secure credential storage is not available on this device');if(newKey.length>512)throw new Error('API key is too long');encryptedKey=safeStorage.encryptString(newKey).toString('base64')}else if(raw.clearKey)encryptedKey=''
  await fs.mkdir(app.getPath('userData'),{recursive:true});await writePrivateFile(aiSettingsFile(),JSON.stringify({endpoint,model,provider,workspaceId,encryptedKey},null,2),'utf8');return {endpoint,model,provider,workspaceId,hasKey:!!encryptedKey,secureStorage:secureStorageAvailable()};
});
ipcMain.handle('ai:complete',async(_,raw)=>{
  if(!raw||typeof raw!=='object'||typeof raw.prompt!=='string'||raw.prompt.length>24000)throw new Error('AI prompt is invalid or too long');
  const settings=await readAISettings(),provider=settings.provider||'compatible';if(!settings.endpoint||!settings.model)throw new Error('Configure an AI endpoint and model in Settings first');
  const endpoint=aiProviderEndpoints[provider]||settings.endpoint,base=validateAIEndpoint(endpoint),url=new URL(base.href),claude=provider==='claude';
  if(aiProviderEndpoints[provider]&&normalizedAIEndpoint(settings.endpoint)!==normalizedAIEndpoint(endpoint))throw new Error('AI provider endpoint does not match saved settings');
  const suffix=claude?'/messages':'/chat/completions';if(!url.pathname.replace(/\/$/,'').endsWith(suffix))url.pathname=`${url.pathname.replace(/\/$/,'')}${suffix}`;
  const headers={'Content-Type':'application/json'};if(settings.encryptedKey){if(!secureStorageAvailable())throw new Error('Secure credential storage is not available');headers.Authorization=`Bearer ${safeStorage.decryptString(Buffer.from(settings.encryptedKey,'base64'))}`}else if(aiProviderEndpoints[provider])throw new Error('Enter an API key for the selected AI provider');
  const instruction='You are a writing assistant. Provide suggestions only. Never claim to have changed the original. Follow the requested language and format.';
  let body;if(claude){headers['anthropic-version']='2023-06-01';if(settings.workspaceId){if(!/^[A-Za-z0-9_-]{1,128}$/.test(settings.workspaceId))throw new Error('Invalid Claude workspace ID');headers['anthropic-workspace-id']=settings.workspaceId}body={model:settings.model,max_tokens:4096,system:instruction,messages:[{role:'user',content:raw.prompt}]}}else{body={model:settings.model,messages:[{role:'system',content:instruction},{role:'user',content:raw.prompt}]};if(provider==='compatible'||provider==='local')body.temperature=0.4}
  const response=await fetch(url,{method:'POST',headers,redirect:'error',signal:AbortSignal.timeout(90000),body:JSON.stringify(body)});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error?.message||`AI request failed (${response.status})`);
  if(claude&&payload.stop_reason==='max_tokens')throw new Error('Claude response was cut short; try a shorter request');
  const content=claude?(Array.isArray(payload.content)?payload.content.filter(block=>block?.type==='text'&&typeof block.text==='string').map(block=>block.text).join('\n'):null):payload.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw new Error('The AI endpoint returned no text');return content.slice(0,24000);
});
ipcMain.handle('weather:forecast',async(_,raw)=>{if(!raw||typeof raw!=='object')throw new Error('Weather request is invalid');const location=String(raw.location||'').trim(),date=String(raw.date||'');if(location.length<2||location.length>100)throw new Error('Enter a town or postal code (not a full street address)');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(`${date}T12:00:00Z`)))throw new Error('Enter a valid shoot date');const language=raw.language==='nl'?'nl':'en';const geoUrl=new URL('https://geocoding-api.open-meteo.com/v1/search');geoUrl.search=new URLSearchParams({name:location,count:'1',language,format:'json'}).toString();const geoResponse=await fetch(geoUrl,{signal:AbortSignal.timeout(15000)});if(!geoResponse.ok)throw new Error(`Weather location lookup failed (${geoResponse.status})`);const geoPayload=await geoResponse.json();const place=geoPayload.results?.[0];if(!place||!Number.isFinite(place.latitude)||!Number.isFinite(place.longitude))throw new Error('No matching town or postal code was found');const forecastUrl=new URL('https://api.open-meteo.com/v1/forecast');forecastUrl.search=new URLSearchParams({latitude:String(place.latitude),longitude:String(place.longitude),daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max,sunrise,sunset,daylight_duration',forecast_days:'16',timezone:place.timezone||'auto'}).toString();const forecastResponse=await fetch(forecastUrl,{signal:AbortSignal.timeout(15000)});if(!forecastResponse.ok)throw new Error(`Weather forecast request failed (${forecastResponse.status})`);const payload=await forecastResponse.json(),daily=payload.daily||{},index=Array.isArray(daily.time)?daily.time.indexOf(date):-1;if(index<0)throw new Error('No forecast is available for this shoot date (the service covers up to 16 days ahead)');const value=(key)=>Array.isArray(daily[key])?daily[key][index]??null:null;return {location:place.name,country:place.country||'',timezone:payload.timezone||place.timezone||'',date,weatherCode:value('weather_code'),sunrise:value('sunrise'),sunset:value('sunset'),daylightDuration:value('daylight_duration'),temperatureMax:value('temperature_2m_max'),temperatureMin:value('temperature_2m_min'),precipitationProbabilityMax:value('precipitation_probability_max'),windSpeedMax:value('wind_speed_10m_max'),fetchedAt:new Date().toISOString(),source:'Open-Meteo',sourceUrl:'https://open-meteo.com/'} });
